//               texld_pp r0, t0, s0; mov_pp r1.xyz, t1; mad_pp r1.xyz, r1, -r0, t2;
//               mul_pp r1.xyz, r1, t2.w; mad_pp r0.xyz, t1, r0, r1; mov_pp oC0, r0
// Both leave the texture alpha untouched on its way to oC0.

